1275	+    /// <summary>
1276	+    /// `required`-Felder in den Seed-DTOs erzwingen bei System.Text.Json nur die Anwesenheit des
1277	+    /// JSON-Schlüssels, nicht dessen Nicht-Null-Wert — ein expliziter JSON-`null`-Wert bleibt also
1278	+    /// trotz `required`-Typisierung zur Laufzeit möglich und würde ohne diese Prüfung zu rohen
1279	+    /// Ausnahmen (z. B. ArgumentNullException bei Dictionary-Keys) statt einer beschreibenden
1280	+    /// Fehlermeldung führen.
1281	+    /// </summary>
1282	+    private static string RequireNonNull(string? value, string errorMessage) =>
1283	+        value ?? throw new InvalidOperationException(errorMessage);
1284	+
1285	+    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
1286	+    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
1287	+    {
1288	+        var digitsStart = 0;
1289	+        while (digitsStart < sitzplatz.Length && char.IsAsciiLetter(sitzplatz[digitsStart]))
1290	+        {
1291	+            digitsStart++;
1292	+        }
1293	+
1294	+        var digitsEnd = digitsStart;
1295	+        while (digitsEnd < sitzplatz.Length && char.IsAsciiDigit(sitzplatz[digitsEnd]))
1296	+        {
1297	+            digitsEnd++;
1298	+        }
1299	+
1300	+        if (digitsStart == 0 || digitsStart == sitzplatz.Length || digitsEnd != sitzplatz.Length
1301	+            || !int.TryParse(sitzplatz[digitsStart..], out var columnNumber))
1302	+        {
1303	+            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
1304	+        }
1305	+
1306	+        var rowLabel = sitzplatz[..digitsStart];
1307	+        return (rowLabel, columnNumber);
1308	+    }
1309	+}
