1059	+
1060	+    public async Task ImportIfEmptyAsync(string jsonFilePath, CancellationToken ct = default)
1061	+    {
1062	+        if (await db.Venues.AnyAsync(ct))
1063	+        {
1064	+            return;
1065	+        }
1066	+
1067	+        if (!File.Exists(jsonFilePath))
1068	+        {
1069	+            throw new InvalidOperationException($"Anfangsdatenbestand '{jsonFilePath}' wurde nicht gefunden.");
1070	+        }
1071	+
