1082	+        }
1083	+
1084	+        if (data is null)
1085	+        {
1086	+            throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht aus '{jsonFilePath}' gelesen werden.");
1087	+        }
1088	+
1089	+        await ImportAsync(data, ct);
1090	+    }
1091	+
1092	+    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
1093	+    {
