2453	+using Microsoft.Data.SqlClient;
2454	+using Microsoft.EntityFrameworkCore;
2455	+using seed_a_backend.Api.Infrastructure;
2456	+
2457	+namespace seed_a_backend.Tests;
2458	+
2459	+/// <summary>
2460	+/// Erstellt für jede Testklasse eine eigene, eindeutig benannte Testdatenbank auf dem echten
2461	+/// SQL Server aus ConnectionStrings__Default (Consistency Convention „Test-Engine für
2462	+/// Nebenläufigkeit“ — kein EF-Core-InMemory-Provider, da gefilterte Unique-Constraints sonst
2463	+/// nicht durchgesetzt würden). Schema wird über die echten EF-Core-Migrations aufgebaut, damit
2464	+/// die Migration selbst mitgetestet wird.
2465	+/// </summary>
2466	+public sealed class SqlServerTestDatabase : IAsyncLifetime
2467	+{
2468	+    private readonly string _connectionString;
2469	+
2470	+    public SqlServerTestDatabase()
2471	+    {
2472	+        var baseConnectionString = Environment.GetEnvironmentVariable("ConnectionStrings__Default")
2473	+            ?? throw new InvalidOperationException("ConnectionStrings__Default ist für die Tests nicht gesetzt.");
2474	+
2475	+        var builder = new SqlConnectionStringBuilder(baseConnectionString)
2476	+        {
2477	+            InitialCatalog = $"seed_a_test_{Guid.NewGuid():N}",
2478	+        };
2479	+        _connectionString = builder.ConnectionString;
2480	+    }
2481	+
2482	+    public AppDbContext CreateContext()
2483	+    {
2484	+        var options = new DbContextOptionsBuilder<AppDbContext>()
2485	+            .UseSqlServer(_connectionString)
2486	+            .Options;
2487	+        return new AppDbContext(options);
2488	+    }
2489	+
2490	+    public async ValueTask InitializeAsync()
2491	+    {
2492	+        await using var db = CreateContext();
2493	+        await db.Database.MigrateAsync();
2494	+    }
2495	+
2496	+    public async ValueTask DisposeAsync()
2497	+    {
2498	+        await using var db = CreateContext();
2499	+        await db.Database.EnsureDeletedAsync();
2500	+    }
2501	+}
