237	    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
238	    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
239	    {
240	        var digitsStart = 0;
241	        while (digitsStart < sitzplatz.Length && char.IsAsciiLetter(sitzplatz[digitsStart]))
242	        {
243	            digitsStart++;
244	        }
245	
246	        var digitsEnd = digitsStart;
247	        while (digitsEnd < sitzplatz.Length && char.IsAsciiDigit(sitzplatz[digitsEnd]))
248	        {
249	            digitsEnd++;
250	        }
251	
252	        if (digitsStart == 0 || digitsStart == sitzplatz.Length || digitsEnd != sitzplatz.Length
253	            || !int.TryParse(sitzplatz[digitsStart..], out var columnNumber))
254	        {
255	            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
256	        }
257	
258	        var rowLabel = sitzplatz[..digitsStart];
259	        return (rowLabel, columnNumber);
